/// 应用命令清单：必须与 src/main.rs 里 generate_handler! 注册的命令一一对应（顺序也保持一致，
/// 方便逐行对照）。`npm run lint` 的 scripts/check-window-capabilities.mjs 会核对两边是否一致。
///
/// 为什么必须登记：Tauri 只在应用登记过这份清单时才检查应用命令的调用权限。不登记，
/// 任何页面——包括登录窗口里打开的外部网站——都能调用下面每一条命令。登记后，每个窗口
/// 只能调用 capabilities/ 里放行给它的 `allow-<命令名>`。
///
/// 构建时会为每条命令在 permissions/autogenerated/ 生成一对 allow-/deny- 权限文件（已 gitignore）。
const APP_COMMANDS: &[&str] = &[
    "set_close_to_tray",
    "get_user_data_dir",
    "get_history_db_path",
    "analytics_send_batch",
    "analytics_shutdown",
    "analytics_start_heartbeat",
    "analytics_stop_heartbeat",
    "open_login_window",
    "show_login_window",
    "setup_cookie_event_monitoring",
    "test_r2_connection",
    "test_webdav_connection",
    "upload_file_stream",
    "test_weibo_connection",
    "upload_to_jd",
    "check_jd_available",
    "upload_to_nowcoder",
    "test_nowcoder_cookie",
    "upload_to_qiyu",
    "check_chrome_installed",
    "check_qiyu_available",
    "upload_to_zhihu",
    "test_zhihu_connection",
    "upload_to_nami",
    "test_nami_connection",
    "fetch_nami_token",
    "upload_to_bilibili",
    "test_bilibili_connection",
    "upload_to_chaoxing",
    "test_chaoxing_connection",
    "get_cli_path_status",
    "add_cli_to_path",
    "remove_cli_from_path",
    "upload_to_smms",
    "upload_to_github",
    "upload_to_imgur",
    "upload_to_s3_compatible",
    "probe_s3_storage",
    "upload_to_webdav",
    "test_webdav_storage",
    "check_image_link",
    "download_url_image",
    "batch_check_links",
    "cancel_batch_check",
    "pause_batch_check",
    "resume_batch_check",
    "clipboard_has_image",
    "read_clipboard_image",
    "set_clipboard_watch",
    "cleanup_clipboard_temp_file",
    "export_text_file",
    "import_text_file",
    "cleanup_owned_temp_file",
    "allow_user_path",
    "get_image_metadata",
    "list_external_uploads",
    "remove_external_uploads",
    "compress_image",
    "cleanup_compressed_files",
    "strip_exif_only",
    "read_image_as_base64",
    "scan_md_folder",
    "get_or_create_secure_key",
    "set_secure_key",
    "open_log_dir",
    "webdav_request",
    "open_path",
    "check_port_free",
    "check_editor_server_status",
    "update_server_config",
    "save_cli_config",
    "get_executable_path",
    "get_taskbar_light",
    "set_tray_default_item",
];

fn main() {
    // analytics/heartbeat.rs 用 option_env! 在编译期读取该密钥。cargo 默认感知不到
    // 环境变量变化，没有这行的话：先前无密钥编译过一次，之后配上密钥重新构建会命中
    // 缓存、继续编出"心跳已禁用"的产物。
    println!("cargo:rerun-if-env-changed=PICNEXUS_GA_API_SECRET");

    // 与 tauri_build::build() 相同的默认属性（含 Windows 资源清单），只多登记应用命令清单
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS));
    if let Err(error) = tauri_build::try_build(attributes) {
        println!("{error:#}");
        std::process::exit(1);
    }
}
